-- Bird View schema v1. Migrations run as a separate owner; applications never do.
CREATE SCHEMA IF NOT EXISTS birdview_private;
CREATE SCHEMA IF NOT EXISTS vault;
DO $$ BEGIN CREATE ROLE birdview_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE birdview_auth NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE birdview_vault NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA birdview_private, vault FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO birdview_runtime,birdview_auth;
GRANT USAGE ON SCHEMA birdview_private TO birdview_runtime,birdview_auth,birdview_vault;
CREATE TABLE IF NOT EXISTS public."user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public."session" (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,"activeOrganizationId" text);
CREATE INDEX IF NOT EXISTS session_user_idx ON public."session"("userId");
CREATE TABLE IF NOT EXISTS public."account" (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("providerId","accountId"));
CREATE INDEX IF NOT EXISTS auth_account_user_idx ON public."account"("userId");
CREATE TABLE IF NOT EXISTS public."verification" (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz DEFAULT now(),"updatedAt" timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.organizations (id text PRIMARY KEY,name text NOT NULL,template text NOT NULL DEFAULT 'services',currency text NOT NULL DEFAULT 'EUR' CHECK(length(currency)=3),timezone text NOT NULL DEFAULT 'Europe/Madrid',modules text[] NOT NULL DEFAULT ARRAY['sales','finance','people','support'],demo boolean NOT NULL DEFAULT false,authorization_version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS public.memberships (id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),user_id text NOT NULL REFERENCES public."user"(id),role text NOT NULL CHECK(role IN('owner','admin','manager','analyst','reader')),department_ids text[] NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,user_id));
CREATE INDEX IF NOT EXISTS membership_user_org_idx ON memberships(user_id,organization_id) WHERE active;
CREATE TABLE IF NOT EXISTS birdview_private.api_principals (id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),owner_id text NOT NULL REFERENCES public."user"(id),key_hash text NOT NULL UNIQUE,permissions text[] NOT NULL,department_ids text[] NOT NULL,active boolean NOT NULL DEFAULT true,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public."user",public."session",public."account",public."verification",public.organizations,public.memberships TO birdview_auth;
GRANT SELECT,INSERT,UPDATE,DELETE ON birdview_private.api_principals TO birdview_auth;
CREATE OR REPLACE FUNCTION birdview_private.context_is_valid() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,birdview_private AS $$
 SELECT EXISTS(SELECT 1 FROM organizations o JOIN memberships m ON m.organization_id=o.id WHERE o.id=nullif(current_setting('app.organization_id',true),'') AND o.deleted_at IS NULL AND m.active AND o.authorization_version::text=current_setting('app.authorization_version',true) AND ((current_setting('app.principal_type',true)='user' AND m.user_id=current_setting('app.user_id',true)) OR (current_setting('app.principal_type',true)='api_key' AND EXISTS(SELECT 1 FROM birdview_private.api_principals k WHERE k.id=current_setting('app.user_id',true) AND k.organization_id=o.id AND k.owner_id=m.user_id AND k.active AND (k.expires_at IS NULL OR k.expires_at>now())))));
$$;
REVOKE ALL ON FUNCTION birdview_private.context_is_valid() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION birdview_private.context_is_valid() TO birdview_runtime,birdview_auth,birdview_vault;
CREATE TABLE IF NOT EXISTS public.accounts (organization_id text NOT NULL REFERENCES organizations(id),id text NOT NULL,department_id text,owner_id text,classification text NOT NULL DEFAULT 'internal' CHECK(classification IN('internal','restricted')),data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(data)='object'),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id));
CREATE INDEX IF NOT EXISTS accounts_org_department_idx ON public.accounts(organization_id,department_id);
ALTER TABLE public.accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.accounts FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.accounts;
CREATE POLICY tenant_isolation ON public.accounts FOR ALL TO birdview_runtime USING (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))) AND (classification='internal' OR current_setting('app.allow_restricted',true)='true')) WITH CHECK (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))) AND (classification='internal' OR current_setting('app.allow_restricted',true)='true'));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.accounts TO birdview_runtime;
ALTER TABLE public.accounts ADD COLUMN IF NOT EXISTS source_connection_ref text GENERATED ALWAYS AS (data#>>'{source,connectionId}') STORED;
ALTER TABLE public.accounts ADD COLUMN IF NOT EXISTS source_external_ref text GENERATED ALWAYS AS (data#>>'{source,externalId}') STORED;
CREATE UNIQUE INDEX IF NOT EXISTS accounts_source_unique ON public.accounts(organization_id,source_connection_ref,source_external_ref) WHERE source_connection_ref IS NOT NULL AND source_external_ref IS NOT NULL;
