DROP POLICY IF EXISTS tenant_isolation ON public.bindings;
CREATE POLICY tenant_isolation ON public.bindings FOR ALL TO birdview_runtime USING (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))) AND (classification='internal' OR current_setting('app.allow_restricted',true)='true')) WITH CHECK (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))) AND (classification='internal' OR current_setting('app.allow_restricted',true)='true'));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.bindings TO birdview_runtime;
ALTER TABLE public.bindings ADD COLUMN IF NOT EXISTS source_connection_ref text GENERATED ALWAYS AS (data#>>'{source,connectionId}') STORED;
ALTER TABLE public.bindings ADD COLUMN IF NOT EXISTS source_external_ref text GENERATED ALWAYS AS (data#>>'{source,externalId}') STORED;
CREATE UNIQUE INDEX IF NOT EXISTS bindings_source_unique ON public.bindings(organization_id,source_connection_ref,source_external_ref) WHERE source_connection_ref IS NOT NULL AND source_external_ref IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.encrypted_credentials (organization_id text NOT NULL REFERENCES organizations(id),id text NOT NULL,department_id text,owner_id text,classification text NOT NULL DEFAULT 'internal' CHECK(classification IN('internal','restricted')),data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(data)='object'),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id));
CREATE INDEX IF NOT EXISTS encrypted_credentials_org_department_idx ON public.encrypted_credentials(organization_id,department_id);
ALTER TABLE public.encrypted_credentials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.encrypted_credentials FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.encrypted_credentials;
CREATE POLICY tenant_isolation ON public.encrypted_credentials FOR ALL TO birdview_runtime USING (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))) AND (classification='internal' OR current_setting('app.allow_restricted',true)='true')) WITH CHECK (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))) AND (classification='internal' OR current_setting('app.allow_restricted',true)='true'));
ALTER TABLE public.encrypted_credentials ADD COLUMN IF NOT EXISTS source_connection_ref text GENERATED ALWAYS AS (data#>>'{source,connectionId}') STORED;
ALTER TABLE public.encrypted_credentials ADD COLUMN IF NOT EXISTS source_external_ref text GENERATED ALWAYS AS (data#>>'{source,externalId}') STORED;
CREATE UNIQUE INDEX IF NOT EXISTS encrypted_credentials_source_unique ON public.encrypted_credentials(organization_id,source_connection_ref,source_external_ref) WHERE source_connection_ref IS NOT NULL AND source_external_ref IS NOT NULL;
