ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_tenant ON public.audit_events FOR ALL TO birdview_runtime USING(organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid()) WITH CHECK(organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid());
